sys_script_include.script:
var SNAppxInteractionData = Class.create();
SNAppxInteractionData.prototype = Object.extendsObject(
	global.AbstractAjaxProcessor,
	{
		createInteraction: function () {
			var requestData = JSON.parse(this.getParameter("sysparm_ctdata"));
			var ctiAjax = new global.CTIAjaxUtility();
			var result = ctiAjax.ctiOpenFrameInteraction(
				requestData.data.snEntityDetails
			);
			var tempResult = {
				jobuuid: requestData.jobuuid,
				command: requestData.command,
				success: false,
				result: {
					result: false,
				},
			};
			if (requestData.data) {
				if (requestData.data.interactionId) {
					tempResult["data"] = {
						interactionId: requestData.data.interactionId,
					};
				}
			}
			if (result.status) {
				if (result.status == "success") {
					tempResult["data"]["success"] = true;
					tempResult["data"]["entitydetails"] = {
						entName: "interaction",
						name: "interaction",
						id: result.fields.interactionSysId,
					};
				}
			}
			return JSON.stringify(tempResult);
		},
		updateInteraction: function () {
			var requestData = JSON.parse(this.getParameter("sysparm_ctdata"));
			var ctiAjax = new global.CTIAjaxUtility();
			var result = ctiAjax.ctiOpenFrameInteraction(
				requestData.data.snEntityDetails
			);
			var tempResult = {
				jobuuid: requestData.jobuuid,
				command: requestData.command,
				success: false,
				result: {
					result: false,
				},
			};
			if (requestData.data) {
				if (requestData.data.interactionId) {
					tempResult["data"] = {
						interactionId: requestData.data.interactionId,
					};
				}
			}
			if (result.status) {
				if (result.status == "success") {
					tempResult["data"]["success"] = true;
				}
			}
			return JSON.stringify(tempResult);
		},
		type: "SNAppxInteractionData",
	}
);
